"use client";

import { useState, useEffect } from "react";
import { useFinanceData } from "@/lib/api";
import { Card, Skeleton, FormModal } from "@/components/finance";
import { useRouter } from "next/navigation";
import { useSubmit } from "@/lib/api";

const LearningPage = () => {
  const router = useRouter();
  const { data: topics, isLoading, isError } = useFinanceData<{ id: number, title: string }[]>("/learning/topics");
  const { data: selectedTopic, isLoading: selectedTopicLoading, isError: selectedTopicError } = useFinanceData<{ content: string }>(`/learning/topic/1`);
  const { data: personalizedLessons, isLoading: personalizedLessonsLoading, isError: personalizedLessonsError } = useFinanceData<{ content: string }[]>("/learning/personalized");

  if (isLoading || selectedTopicLoading || personalizedLessonsLoading) return <Skeleton />;
  if (isError || selectedTopicError || personalizedLessonsError) return <div>Error loading data</div>;

  return (
    <div className="flex flex-col h-screen">
      <div className="flex-1 flex">
        <div className="w-1/4 p-4">
          <h2 className="text-xl font-bold">Topics</h2>
          <ul>
            {topics.map(topic => (
              <li key={topic.id} className="cursor-pointer hover:text-blue-500" onClick={() => router.push(`/learning/topic/${topic.id}`)}>
                {topic.title}
              </li>
            ))}
          </ul>
        </div>
        <div className="flex-1 p-4">
          <h2 className="text-xl font-bold">Selected Topic</h2>
          <div dangerouslySetInnerHTML={{ __html: selectedTopic.content }} />
        </div>
      </div>
      <div className="p-4">
        <h2 className="text-xl font-bold">Personalized Lessons</h2>
        <div dangerouslySetInnerHTML={{ __html: personalizedLessons.map(lesson => lesson.content).join("<hr>") }} />
      </div>
    </div>
  );
};

export default LearningPage;
